//! CLI-owned view data.
//!
//! Handlers map [`crate::forge`] values into these types; the templates under
//! `src/templates` are the only thing that turns them into text.
//!
//! Table layout follows one rule: columns separated by a single space, each
//! column but the last padded to its widest rendered cell, header included when
//! one is shown. The width of each padded column is resolved here, because the
//! template pads with `pad_right(<width>)` — the same split standout's own help
//! rendering uses, where `HelpData` carries `options_width` and the template
//! carries the `pad_right` call.

use serde::Serialize;

use crate::forge::{Check, PullRequest, Repository};

/// Rendered width of a cell. The frozen forge state is ASCII, so counting
/// characters is counting terminal columns.
fn width(cell: &str) -> usize {
    cell.chars().count()
}

pub const NUMBER_HEADER: &str = "NUMBER";
pub const TITLE_HEADER: &str = "TITLE";
pub const STATE_HEADER: &str = "STATE";

#[derive(Serialize)]
pub struct AuthStatusView {
    pub username: String,
}

impl AuthStatusView {
    pub fn new(username: &str) -> Self {
        AuthStatusView {
            username: username.to_string(),
        }
    }
}

#[derive(Serialize)]
pub struct RepoView {
    pub name: String,
    pub description: String,
    pub visibility: String,
}

impl From<&Repository> for RepoView {
    fn from(repo: &Repository) -> Self {
        RepoView {
            name: repo.name.to_string(),
            description: repo.description.to_string(),
            visibility: repo.visibility.as_str().to_string(),
        }
    }
}

#[derive(Serialize)]
pub struct PrRow {
    pub number: u64,
    pub title: String,
    pub state: String,
}

#[derive(Serialize)]
pub struct PrListHeaders {
    pub number: &'static str,
    pub title: &'static str,
    pub state: &'static str,
}

#[derive(Serialize)]
pub struct PrListWidths {
    pub number: usize,
    pub title: usize,
}

#[derive(Serialize)]
pub struct PrListView {
    pub headers: PrListHeaders,
    pub widths: PrListWidths,
    pub pull_requests: Vec<PrRow>,
}

impl PrListView {
    pub fn new(pull_requests: &[PullRequest]) -> Self {
        let rows: Vec<PrRow> = pull_requests
            .iter()
            .map(|pr| PrRow {
                number: pr.number,
                title: pr.title.to_string(),
                state: pr.state.as_str().to_string(),
            })
            .collect();

        let widths = PrListWidths {
            number: rows
                .iter()
                .map(|row| width(&row.number.to_string()))
                .chain([width(NUMBER_HEADER)])
                .max()
                .unwrap_or(0),
            title: rows
                .iter()
                .map(|row| width(&row.title))
                .chain([width(TITLE_HEADER)])
                .max()
                .unwrap_or(0),
        };

        PrListView {
            headers: PrListHeaders {
                number: NUMBER_HEADER,
                title: TITLE_HEADER,
                state: STATE_HEADER,
            },
            widths,
            pull_requests: rows,
        }
    }
}

