    fn from(pr: &PullRequest) -> Self {
        PrView {
            number: pr.number,
            title: pr.title.to_string(),
            state: pr.state.as_str().to_string(),
            author: pr.author.to_string(),
        }
    }
}

#[derive(Serialize)]
pub struct CheckRow {
    pub name: String,
    pub status: String,
}

#[derive(Serialize)]
pub struct ChecksListWidths {
    pub name: usize,
}

/// `pr checks list` is headerless, so only the rows decide the name column.
#[derive(Serialize)]
pub struct ChecksListView {
    pub widths: ChecksListWidths,
    pub checks: Vec<CheckRow>,
}

impl ChecksListView {
    pub fn new(checks: &[Check]) -> Self {
        let rows: Vec<CheckRow> = checks
            .iter()
            .map(|check| CheckRow {
                name: check.name.to_string(),
                status: check.status.as_str().to_string(),
            })
            .collect();

        let widths = ChecksListWidths {
            name: rows.iter().map(|row| width(&row.name)).max().unwrap_or(0),
        };

        ChecksListView {
            widths,
            checks: rows,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::forge::Forge;

    #[test]
    fn pr_list_columns_are_as_wide_as_their_widest_cell_header_included() {
        let view = PrListView::new(Forge::new().pull_requests());
        // "NUMBER" is wider than any of 1, 2, 3.
        assert_eq!(view.widths.number, 6);
        // "Add pager" is wider than "TITLE".
        assert_eq!(view.widths.title, 9);
    }

    #[test]
    fn checks_columns_ignore_headers_because_none_are_shown() {
        let forge = Forge::new();
        let pr = forge.pull_request("1").unwrap();
        let view = ChecksListView::new(forge.checks(pr));
        assert_eq!(view.widths.name, 5); // "build"
        assert_eq!(view.checks.len(), 2);
    }

    #[test]
    fn a_pull_request_without_checks_yields_no_rows() {
        let forge = Forge::new();
        let pr = forge.pull_request("3").unwrap();
        let view = ChecksListView::new(forge.checks(pr));
        assert_eq!(view.widths.name, 0);
        assert!(view.checks.is_empty());
    }
}

