//! `--json <fields>` — machine output with field selection.
//!
//! The human surface is a template; this is the other one. The bytes are
//! assembled here and handed back as `Output::Binary`, which is the one
//! `Output` shape that reaches stdout without a render pass — no theme, no
//! style tags, no pager, no prose. That is what makes the JSON identical on an
//! attended color-capable terminal and in a pipe.

use serde_json::{Map, Value};

use crate::diagnostic;
use crate::forge::{Check, PullRequest};

pub const PULL_REQUEST_FIELDS: &[&str] = &["number", "title", "state", "author", "draft"];
pub const CHECK_FIELDS: &[&str] = &["name", "status"];

/// The fields a `--json` argument selected, in the order they were asked for.
pub struct Selection {
    fields: Vec<&'static str>,
}

impl Selection {
    /// Resolve a comma-separated field list against the fields a command
    /// offers. An unknown field is a domain error, not a usage error.
    pub fn parse(spec: &str, available: &'static [&'static str]) -> Result<Self, anyhow::Error> {
        let mut fields = Vec::new();
        for requested in spec.split(',') {
            let requested = requested.trim();
            match available.iter().find(|field| **field == requested) {
                Some(field) => fields.push(*field),
                None => return Err(unknown_field(requested, available)),
            }
        }
        Ok(Selection { fields })
    }

    fn object(&self, value_of: impl Fn(&str) -> Value) -> Value {
        let mut object = Map::new();
        for field in &self.fields {
            object.insert((*field).to_string(), value_of(field));
        }
        Value::Object(object)
    }
}

fn unknown_field(field: &str, available: &[&str]) -> anyhow::Error {
    diagnostic::domain_error(format!(
        "ghlike: unknown JSON field: {field:?}\nvalid fields: {}\n",
        available.join(", ")
    ))
}

fn pull_request_value(pr: &PullRequest, field: &str) -> Value {
    match field {
        "number" => Value::from(pr.number),
        "title" => Value::from(pr.title),
        "state" => Value::from(pr.state.as_str()),
        "author" => Value::from(pr.author),
        "draft" => Value::from(pr.draft),
        // `Selection::parse` rejects anything else before it gets here.
        _ => Value::Null,
    }
}

fn check_value(check: &Check, field: &str) -> Value {
    match field {
        "name" => Value::from(check.name),
        "status" => Value::from(check.status.as_str()),
        _ => Value::Null,
    }
}

/// Serialize one JSON document as the bytes a `Output::Binary` carries.
fn bytes(value: &Value) -> Vec<u8> {
    let mut bytes = serde_json::to_vec(value).expect("view values are plain JSON scalars");
    bytes.push(b'\n');
    bytes
}

pub fn pull_request_array(pull_requests: &[PullRequest], selection: &Selection) -> Vec<u8> {
    let array = Value::Array(
        pull_requests
            .iter()
            .map(|pr| selection.object(|field| pull_request_value(pr, field)))
            .collect(),
    );
    bytes(&array)
}

pub fn pull_request_object(pull_request: &PullRequest, selection: &Selection) -> Vec<u8> {
    bytes(&selection.object(|field| pull_request_value(pull_request, field)))
}

pub fn check_array(checks: &[Check], selection: &Selection) -> Vec<u8> {
    let array = Value::Array(
        checks
            .iter()
            .map(|check| selection.object(|field| check_value(check, field)))
            .collect(),
    );
    bytes(&array)
}

