//! Domain diagnostics.
//!
//! `ghlike` owns the exact stderr wording of its domain errors — `ghlike:
//! repository not found: …` and friends — and their exit status 1. An ordinary
//! handler error would be reframed as `Error: {error}` by the framework, so the
//! diagnostic goes back through `ExternalFailure`, whose contract is "verbatim
//! stderr payload, no `Error:` prefix and no trailing newline" and whose status
//! is the exact one declared here. Handlers still never print or exit
//! themselves; `App::run` performs the write.

use standout::cli::ExternalFailure;

/// Status 1 in `SPEC.md`'s table: unknown repo, unknown PR, unknown `--json`
/// field.
const DOMAIN_ERROR_STATUS: u8 = 1;

/// Wrap a fully worded diagnostic — trailing newline included, since nothing
/// downstream adds one — as a status-1 failure.
pub fn domain_error(diagnostic: impl Into<String>) -> anyhow::Error {
    ExternalFailure::new(DOMAIN_ERROR_STATUS, diagnostic.into())
        .expect("1 is nonzero")
        .into()
}

pub fn repository_not_found(reference: &str) -> anyhow::Error {
    domain_error(format!("ghlike: repository not found: {reference}\n"))
}

pub fn pull_request_not_found(reference: &str) -> anyhow::Error {
    domain_error(format!("ghlike: no pull request found: {reference}\n"))
}

