//! Handlers: the adapters between parsed arguments and the forge.
//!
//! Each one reads the frozen forge out of app state, asks it a question, and
//! returns view data. Nothing here prints, styles, or exits. The `--json`
//! branch returns `Output::Binary` instead of `Output::Render` — that is a
//! choice of output *shape*, not a branch on the caller's output mode, which
//! standout deliberately keeps out of `CommandContext`.

use standout::cli::{CommandContext, Output};
use standout::handler;

use crate::diagnostic;
use crate::forge::Forge;
use crate::machine::{self, Selection, CHECK_FIELDS, PULL_REQUEST_FIELDS};
use crate::view::{AuthStatusView, ChecksListView, PrListView, PrView, RepoView};

fn forge(ctx: &CommandContext) -> Result<&Forge, anyhow::Error> {
    ctx.app_state.get_required::<Forge>()
}

pub mod auth {
    use super::*;

    #[handler]
    pub fn status(#[ctx] ctx: &CommandContext) -> Result<Output<AuthStatusView>, anyhow::Error> {
        let forge = forge(ctx)?;
        Ok(Output::Render(AuthStatusView::new(forge.viewer())))
    }
}

pub mod repo {
    use super::*;

    #[handler]
    pub fn view(
        #[arg] repository: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<RepoView>, anyhow::Error> {
        let forge = forge(ctx)?;
        match forge.repository(&repository) {
            Some(found) => Ok(Output::Render(RepoView::from(found))),
            None => Err(diagnostic::repository_not_found(&repository)),
        }
    }
}

pub mod pr {
    use super::*;

