//! `ghlike` — a forge client in the gh mold.
//!
//! Clap owns the command tree and the flags; standout owns dispatch, the
//! templates that render the human surface, and the final write. The frozen
//! forge lives in `forge`, which knows nothing about either.

mod diagnostic;
mod forge;
mod handlers;
mod machine;
mod view;

use clap::{CommandFactory, Parser, Subcommand};
use standout::cli::{App, Dispatch};
use standout::{embed_styles, embed_templates};

use forge::Forge;

#[derive(Parser)]
#[command(name = "ghlike", about = "A forge client that serves humans and machines")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    /// Authentication state
    #[dispatch(nested)]
    Auth(#[command(subcommand)] AuthCommands),
    /// Repositories
    #[dispatch(nested)]
    Repo(#[command(subcommand)] RepoCommands),
    /// Pull requests
    #[dispatch(nested)]
    Pr(#[command(subcommand)] PrCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers::auth)]
enum AuthCommands {
    /// Show the account this client is authenticated as
    #[dispatch(pure)]
    Status,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers::repo)]
enum RepoCommands {
    /// Show a repository
    #[dispatch(pure)]
    View {
        /// The repository, as owner/name
        #[arg(value_name = "OWNER/NAME")]
        repository: String,
    },
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers::pr)]
enum PrCommands {
    /// List pull requests
    #[dispatch(pure)]
    List {
        /// Emit JSON with only these comma-separated fields
        #[arg(long, value_name = "FIELDS")]
        json: Option<String>,
    },
    /// Show a pull request
    #[dispatch(pure)]
    View {
        /// The pull request number
        #[arg(value_name = "NUMBER")]
