tool_use_result.originalFile:
//! `--json <fields>` — machine output with field selection.
//!
//! The human surface is a template; this is the other one. The bytes are
//! assembled here and handed back as `Output::Binary`, which is the one
//! `Output` shape that reaches stdout without a render pass — no theme, no
//! style tags, no pager, no prose. That is what makes the JSON identical on an
//! attended color-capable terminal and in a pipe.

use serde_json::{Map, Value};

use crate::diagnostic;
use crate::forge::{Check, PullRequest};

pub const PULL_REQUEST_FIELDS: &[&str] = &["number", "title", "state", "author", "draft"];
pub const CHECK_FIELDS: &[&str] = &["name", "status"];

/// The fields a `--json` argument selected, in the order they were asked for.
pub struct Selection {
    fields: Vec<&'static str>,
}

impl Selection {
    /// Resolve a comma-separated field list against the fields a command
    /// offers. An unknown field is a domain error, not a usage error.
    pub fn parse(spec: &str, available: &'static [&'static str]) -> Result<Self, anyhow::Error> {
        let mut fields = Vec::new();
        for requested in spec.split(',') {
            let requested = requested.trim();
            match available.iter().find(|field| **field == requested) {
                Some(field) => fields.push(*field),
                None => return Err(unknown_field(requested, available)),
            }
        }
        Ok(Selection { fields })
    }

    fn object(&self, value_of: impl Fn(&str) -> Value) -> Value {
        let mut object = Map::new();
        for field in &self.fields {
            object.insert((*field).to_string(), value_of(field));
        }
        Value::Object(object)
    }
}

fn unknown_field(field: &str, available: &[&str]) -> anyhow::Error {
    diagnostic::domain_error(format!(
        "ghlike: unknown JSON field: {field:?}\nvalid fields: {}\n",
        available.join(", ")
    ))
}

fn pull_request_value(pr: &PullRequest, field: &str) -> Value {
    match field {
        "number" => Value::from(pr.number),
        "title" => Value::from(pr.title),
        "state" => Value::from(pr.state.as_str()),
        "author" => Value::from(pr.author),
        "draft" => Value::from(pr.draft),
        // `Selection::parse` rejects anything else before it gets here.
        _ => Value::Null,
    }
}

fn check_value(check: &Check, field: &str) -> Value {
    match field {
        "name" => Value::from(check.name),
        "status" => Value::from(check.status.as_str()),
        _ => Value::Null,
    }
}

/// Serialize one JSON document as the bytes a `Output::Binary` carries.
fn bytes(value: &Value) -> Vec<u8> {
    let mut bytes = serde_json::to_vec(value).expect("view values are plain JSON scalars");
    bytes.push(b'\n');
    bytes
}

pub fn pull_request_array(pull_requests: &[PullRequest], selection: &Selection) -> Vec<u8> {
    let array = Value::Array(
        pull_requests
            .iter()
            .map(|pr| selection.object(|field| pull_request_value(pr, field)))
            .collect(),
    );
    bytes(&array)
}

pub fn pull_request_object(pull_request: &PullRequest, selection: &Selection) -> Vec<u8> {
    bytes(&selection.object(|field| pull_request_value(pull_request, field)))
}

pub fn check_array(checks: &[Check], selection: &Selection) -> Vec<u8> {
    let array = Value::Array(
        checks
            .iter()
            .map(|check| selection.object(|field| check_value(check, field)))
            .collect(),
    );
    bytes(&array)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::forge::Forge;

    fn utf8(bytes: Vec<u8>) -> String {
        String::from_utf8(bytes).unwrap()
    }

    #[test]
    fn an_array_carries_exactly_the_requested_fields_in_order() {
        let selection = Selection::parse("title,number", PULL_REQUEST_FIELDS).unwrap();
        let rendered = utf8(pull_request_array(Forge::new().pull_requests(), &selection));
        assert_eq!(
            rendered,
            "[{\"title\":\"Add pager\",\"number\":1},\
             {\"title\":\"Fix theme\",\"number\":2},\
             {\"title\":\"Docs pass\",\"number\":3}]\n"
        );
    }

    #[test]
    fn numbers_and_drafts_keep_their_json_types() {
        let selection = Selection::parse("number,draft,state", PULL_REQUEST_FIELDS).unwrap();
        let forge = Forge::new();
        let pr = forge.pull_request("3").unwrap();
        let rendered = utf8(pull_request_object(pr, &selection));
        assert_eq!(rendered, "{\"number\":3,\"draft\":true,\"state\":\"open\"}\n");
    }

    #[test]
    fn a_pull_request_without_checks_serializes_an_empty_array() {
        let selection = Selection::parse("name,status", CHECK_FIELDS).unwrap();
        let forge = Forge::new();
        let pr = forge.pull_request("3").unwrap();
        assert_eq!(utf8(check_array(forge.checks(pr), &selection)), "[]\n");
    }

    #[test]
    fn an_unknown_field_is_rejected_by_name() {
        let error = Selection::parse("number,nope", PULL_REQUEST_FIELDS).unwrap_err();
        let rendered = error.to_string();
        assert!(rendered.contains("\"nope\""), "{rendered}");
        assert!(rendered.contains("number, title, state, author, draft"), "{rendered}");
    }
}

//! Handlers: the adapters between parsed arguments and the forge.
//!
//! Each one reads the frozen forge out of app state, asks it a question, and
//! returns view data. Nothing here prints, styles, or exits. The `--json`
//! branch returns `Output::Binary` instead of `Output::Render` — that is a
//! choice of output *shape*, not a branch on the caller's output mode, which
//! standout deliberately keeps out of `CommandContext`.

use standout::cli::{CommandContext, Output};
use standout::handler;

use crate::diagnostic;
use crate::forge::Forge;
use crate::machine::{self, Selection, CHECK_FIELDS, PULL_REQUEST_FIELDS};
use crate::view::{AuthStatusView, ChecksListView, PrListView, PrView, RepoView};

fn forge(ctx: &CommandContext) -> Result<&Forge, anyhow::Error> {
    ctx.app_state.get_required::<Forge>()
}

pub mod auth {
    use super::*;

    #[handler]
    pub fn status(#[ctx] ctx: &CommandContext) -> Result<Output<AuthStatusView>, anyhow::Error> {
        let forge = forge(ctx)?;
        Ok(Output::Render(AuthStatusView::new(forge.viewer())))
    }
}

pub mod repo {
    use super::*;

    #[handler]
    pub fn view(
        #[arg] repository: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<RepoView>, anyhow::Error> {
        let forge = forge(ctx)?;
        match forge.repository(&repository) {
            Some(found) => Ok(Output::Render(RepoView::from(found))),
            None => Err(diagnostic::repository_not_found(&repository)),
        }
    }
}

pub mod pr {
    use super::*;

    #[handler]
    pub fn list(
        #[arg] json: Option<String>,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<PrListView>, anyhow::Error> {
        let forge = forge(ctx)?;
        let pull_requests = forge.pull_requests();

        if let Some(spec) = json {
            let selection = Selection::parse(&spec, PULL_REQUEST_FIELDS)?;
            return Ok(Output::Binary {
                data: machine::pull_request_array(pull_requests, &selection),
                filename: "pr-list.json".to_string(),
            });
        }

        Ok(Output::Render(PrListView::new(pull_requests)))
    }

    #[handler]
    pub fn view(
        #[arg] number: String,
        #[arg] json: Option<String>,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<PrView>, anyhow::Error> {
        let forge = forge(ctx)?;
        let Some(pull_request) = forge.pull_request(&number) else {
            return Err(diagnostic::pull_request_not_found(&number));
        };

        if let Some(spec) = json {
            let selection = Selection::parse(&spec, PULL_REQUEST_FIELDS)?;
            return Ok(Output::Binary {
                data: machine::pull_request_object(pull_request, &selection),
                filename: "pr-view.json".to_string(),
            });
        }

        Ok(Output::Render(PrView::from(pull_request)))
    }
}

pub mod pr_checks {
    use super::*;

    #[handler]
    pub fn list(
        #[arg] number: String,
        #[arg] json: Option<String>,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ChecksListView>, anyhow::Error> {
        let forge = forge(ctx)?;
        let Some(pull_request) = forge.pull_request(&number) else {
            return Err(diagnostic::pull_request_not_found(&number));
        };
        let checks = forge.checks(pull_request);

        if let Some(spec) = json {
            let selection = Selection::parse(&spec, CHECK_FIELDS)?;
            return Ok(Output::Binary {
                data: machine::check_array(checks, &selection),
                filename: "pr-checks-list.json".to_string(),
            });
        }

        Ok(Output::Render(ChecksListView::new(checks)))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use standout::cli::Extensions;

    fn context() -> CommandContext {
        let mut app_state = Extensions::new();
        app_state.insert(Forge::new());
        CommandContext {
            app_state: app_state.into(),
            ..Default::default()
        }
    }

    fn rendered<T>(output: Output<T>) -> T
    where
        T: serde::Serialize,
    {
        match output {
            Output::Render(data) => data,
            _ => panic!("expected rendered view data"),
        }
    }

    fn binary<T>(output: Output<T>) -> String
    where
        T: serde::Serialize,
    {
        match output {
            Output::Binary { data, .. } => String::from_utf8(data).unwrap(),
            _ => panic!("expected binary JSON bytes"),
        }
    }

    #[test]
    fn auth_status_names_the_viewer() {
        let view = rendered(auth::status(&context()).unwrap());
        assert_eq!(view.username, "corpus-bot");
    }

    #[test]
    fn repo_view_maps_a_known_repository() {
        let view = rendered(repo::view("demo/beta".to_string(), &context()).unwrap());
        assert_eq!(view.name, "demo/beta");
        assert_eq!(view.description, "Beta tools");
        assert_eq!(view.visibility, "private");
    }

    #[test]
    fn repo_view_reports_an_unknown_repository_by_name() {
        let error = repo::view("demo/gamma".to_string(), &context()).unwrap_err();
        assert!(
            error.to_string().contains("ghlike: repository not found: demo/gamma"),
            "{error}"
        );
    }

    #[test]
    fn pr_view_reports_an_unknown_number_by_the_reference_typed() {
        let error = pr::view("99".to_string(), None, &context()).unwrap_err();
        assert!(
            error.to_string().contains("ghlike: no pull request found: 99"),
            "{error}"
        );
    }

    #[test]
    fn pr_list_json_selects_fields_without_a_render() {
        let output = pr::list(Some("number,state".to_string()), &context()).unwrap();
        assert_eq!(
            binary(output),
            "[{\"number\":1,\"state\":\"open\"},\
             {\"number\":2,\"state\":\"merged\"},\
             {\"number\":3,\"state\":\"open\"}]\n"
        );
    }

    #[test]
    fn pr_checks_list_json_is_an_array_even_when_empty() {
        let output = pr_checks::list(
            "3".to_string(),
            Some("name,status".to_string()),
            &context(),
        )
        .unwrap();
        assert_eq!(binary(output), "[]\n");
    }

    #[test]
    fn an_unknown_json_field_fails_before_any_output() {
        let error = pr::list(Some("number,branch".to_string()), &context()).unwrap_err();
        assert!(error.to_string().contains("\"branch\""), "{error}");
    }
}

